<?php

namespace webcoder31\ezxmldsig\Demo;

/**
 * The certificates and keys of demo/certs/, generated by
 * `bin/gen-test-certs --demo`.
 *
 * Their private keys are public (see demo/certs/README.md): they only serve
 * the demo.
 */
final class Certs
{
    /** Password of sign.key.pem. */
    const SIGN_KEY_PASSWORD = 'signKeyPassword';

    /** Password of crypt.key.pem. */
    const CRYPT_KEY_PASSWORD = 'cryptKeyPassword';

    /** The subject fields the receiver expects by default: those of
    sign.cert.pem that the CA does not give to other holders. */
    const EXPECTED_SUBJECT = ['O' => 'Lothbrok Ltd', 'OU' => 'Signature Dept'];

    /**
     * Returns the path of a file of demo/certs/.
     *
     * @param string $name File name, e.g. "sign.cert.pem".
     *
     * @return string
     */
    public static function path($name)
    {
        return dirname(__DIR__) . '/certs/' . $name;
    }

    /**
     * Returns the CA certificates the receiver trusts: the intermediate CA
     * that issued sign.cert.pem, and its root.
     *
     * @return string[]
     */
    public static function trustedCAs()
    {
        return [self::path('intermediate.cert.pem'), self::path('root.cert.pem')];
    }
}
